assign err_dC[DEPTH-1] = in_err_iC;

always_ff @( posedge clk_iA or negedge rst_niA )
  begin
    if (!rst_niA)
      begin
        valid_qA <= '0;
      end
    else
      begin
        valid_qA <= valid_dA;
      end
  end

always_ff @( posedge clk_iB or negedge rst_niB )
  begin
    if (!rst_niB)
      begin
        valid_qB <= '0;
      end
    else
      begin
        valid_qB <= valid_dB;
      end
  end

always_ff @( posedge clk_iC or negedge rst_niC )
  begin
    if (!rst_niC)
      begin
        valid_qC <= '0;
      end
    else
      begin
        valid_qC <= valid_dC;
      end
  end
for(genvar i = 0; i<DEPTH; i++)
  begin : g_fifo_regs

    always_ff @( posedge clk_iA or negedge rst_niA )
      begin
        if (!rst_niA)
          begin
            rdata_qA[i] <= '0;
            err_qA[i] <= '0;
          end
        else
          if (entry_enA[i])
            begin
              rdata_qA[i] <= rdata_dA[i];
              err_qA[i] <= err_dA[i];
            end

      end

    always_ff @( posedge clk_iB or negedge rst_niB )
      begin
        if (!rst_niB)
          begin
            rdata_qB[i] <= '0;
            err_qB[i] <= '0;
          end
        else
          if (entry_enB[i])
            begin
              rdata_qB[i] <= rdata_dB[i];
              err_qB[i] <= err_dB[i];
            end

      end

    always_ff @( posedge clk_iC or negedge rst_niC )
      begin
        if (!rst_niC)
          begin
            rdata_qC[i] <= '0;
            err_qC[i] <= '0;
          end
        else
          if (entry_enC[i])
            begin
              rdata_qC[i] <= rdata_dC[i];
              err_qC[i] <= err_dC[i];
            end

      end
  end

majorityVoter #(.WIDTH( ((((DEPTH-1)>0) ? (DEPTH-1) : - ( DEPTH-1 ) )+1) )) err_qVoterA (
    .inA(err_qA),
    .inB(err_qB),
    .inC(err_qC),
    .out(err_qVotedA),
    .tmrErr(err_qTmrErrorA)
  );

