    .inB(rdata_qB),
    .inC(rdata_qC),
    .out(rdata_qVotedA),
    .tmrErr(rdata_qTmrErrorA)
  );

majorityVoter #(.WIDTH( ((((DEPTH-1)>0) ? (DEPTH-1) : - ( DEPTH-1 ) )+1) )) valid_qVoterA (
    .inA(valid_qA),
    .inB(valid_qB),
    .inC(valid_qC),
    .out(valid_qVotedA),
    .tmrErr(valid_qTmrErrorA)
  );
assign tmrErrorA = err_qTmrErrorA|instr_addr_qTmrErrorA|rdata_qTmrErrorA|valid_qTmrErrorA;

majorityVoter #(.WIDTH( ((((DEPTH-1)>0) ? (DEPTH-1) : - ( DEPTH-1 ) )+1) )) err_qVoterB (
